cat > /tmp/check.js <<'EOF'
const { chromium } = require('/Users/yuvalt/personal/visual-renderer/bench/versus-browser/tooling/node_modules/playwright');
const sizes = { square:[1080,1080], landscape:[1920,1080], story:[1080,1920] };
(async () => {
  const b = await chromium.launch();
  for (const [n,[w,h]] of Object.entries(sizes)) {
    const p = await b.newPage({ viewport:{width:w,height:h} });
    await p.goto('file://' + process.argv[2]);
    await p.waitForTimeout(600);
    const r = await p.evaluate(() => {
      const out = { problems: [], boxes: {} };
      const sel = '.header,.event-name,.header img,.avatar,.avatar img,.name,.role,.title,.meta,.btn,.footer,.body,.inner';
      document.querySelectorAll(sel).forEach(el => {
        const b = el.getBoundingClientRect();
        const key = (el.className || el.tagName) + '';
        out.boxes[key] = [Math.round(b.x),Math.round(b.y),Math.round(b.width),Math.round(b.height)];
        if (b.left < -0.5 || b.top < -0.5 || b.right > innerWidth+0.5 || b.bottom > innerHeight+0.5)
          out.problems.push(`OUT-OF-BOUNDS ${key}: ${JSON.stringify(out.boxes[key])}`);
        if (el.scrollWidth > el.clientWidth + 1 || el.scrollHeight > el.clientHeight + 1)
          out.problems.push(`CLIPPED ${key}: scroll ${el.scrollWidth}x${el.scrollHeight} vs client ${el.clientWidth}x${el.clientHeight}`);
      });
      const a = document.querySelector('.avatar').getBoundingClientRect();
      if (Math.abs(a.width - a.height) > 0.5) out.problems.push(`AVATAR NOT SQUARE ${a.width}x${a.height}`);
      // overlap check between key text blocks
      const items = ['.header','.speaker','.title','.footer'].map(s => [s, document.querySelector(s).getBoundingClientRect()]);
      for (let i=0;i<items.length;i++) for (let j=i+1;j<items.length;j++) {
        const [n1,r1]=items[i],[n2,r2]=items[j];
        const ox = Math.min(r1.right,r2.right)-Math.max(r1.left,r2.left);
        const oy = Math.min(r1.bottom,r2.bottom)-Math.max(r1.top,r2.top);
        if (ox > 1 && oy > 1) out.problems.push(`OVERLAP ${n1} / ${n2} by ${Math.round(ox)}x${Math.round(oy)}`);
      }
      out.docOverflow = [document.documentElement.scrollWidth, document.documentElement.scrollHeight];
      out.titleLines = Math.round(document.querySelector('.title').getBoundingClientRect().height /
        parseFloat(getComputedStyle(document.querySelector('.title')).lineHeight));
      return out;
    });
    console.log(`\n=== ${n} ${w}x${h} === doc:${r.docOverflow} titleLines:${r.titleLines}`);
    console.log(r.problems.length ? r.problems.join('\n') : '  OK - no problems');
    await p.close();
  }
  await b.close();
})();
EOF
